def tail(src,o,note):
    h=H('원문과 같은 주제 글')+P('▸ 원문 · <a href="%s%s">%s</a>'%(N,src,T[src]))
    for i in o: h+=L(i,T[i])
    return h+P(note+' 정리 · 낭만 부동산 분석 플랫폼.')
